<?php defined('ABSPATH') || exit;$editing=$record instanceof \GreatMarketrealmCompanion\Modules\DungeonMaster\Models\EvidenceRecord;$recordType=$editing?$record->recordType():'evidence';$kind=$editing?$record->evidenceKind():'clue';$selectedThreads=$editing?$record->threadIds():[];$selectedLocations=$editing?$record->locationIds():[];$selectedPersonae=$editing?$record->personaIds():[]; ?>
<form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="gmrc-evidence-form__body"><input type="hidden" name="action" value="gmrc_app_request"><input type="hidden" name="gmrc_route" value="<?php echo esc_attr($route); ?>"><input type="hidden" name="_method" value="<?php echo $editing?'PUT':'POST'; ?>"><input type="hidden" name="gmrc_nonce" value="<?php echo esc_attr(wp_create_nonce('gmrc_dm_evidence_'.$campaign->id())); ?>">
<div class="gmrc-evidence-form__row"><label>Record type<select name="record_type"><option value="evidence" <?php selected($recordType,'evidence'); ?>>Evidence</option><option value="thread" <?php selected($recordType,'thread'); ?>>Thread / mystery</option></select></label><label>Evidence kind<select name="evidence_kind"><?php foreach(\GreatMarketrealmCompanion\Modules\DungeonMaster\Models\EvidenceRecord::EVIDENCE_KINDS as $value): ?><option value="<?php echo esc_attr($value); ?>" <?php selected($kind,$value); ?>><?php echo esc_html(ucfirst($value)); ?></option><?php endforeach; ?></select></label><label>Visibility<select name="visibility"><option value="keeper" <?php selected($editing?$record->visibility():'keeper','keeper'); ?>>Keeper only</option><option value="players" <?php selected($editing?$record->visibility():'keeper','players'); ?>>Player-visible</option></select></label></div>
<label>Name / question<input type="text" name="name" maxlength="180" required value="<?php echo esc_attr($editing?$record->name():''); ?>" placeholder="Torn shipping manifest, Who emptied the cold vault?…"></label><label>At-a-glance summary<textarea name="summary" rows="4" maxlength="900" placeholder="What matters immediately about this evidence or thread?"><?php echo esc_textarea($editing?$record->summary():''); ?></textarea></label><label>Private Keeper notes<textarea name="keeper_notes" rows="10" maxlength="20000" placeholder="Meaning, provenance, false leads, consequences, what the players do not know yet…"><?php echo esc_textarea($editing?$record->notes():''); ?></textarea></label>
<div class="gmrc-evidence-links"><fieldset><legend>Threads</legend><p>Attach evidence to one or more active mysteries. Thread records themselves ignore this selection.</p><?php if(($threads??[])===[]): ?><em>No open threads yet.</em><?php else: ?><?php foreach($threads as $thread): if($editing&&$thread->id()===$record->id()){continue;} ?><label class="gmrc-evidence-check"><input type="checkbox" name="thread_ids[]" value="<?php echo esc_attr($thread->id()); ?>" <?php checked(in_array($thread->id(),$selectedThreads,true)); ?>> <span><?php echo esc_html($thread->name()); ?></span></label><?php endforeach; ?><?php endif; ?></fieldset><fieldset><legend>Locations</legend><?php if(($locations??[])===[]): ?><em>No active Gazetteer locations yet.</em><?php else: ?><?php foreach($locations as $location): ?><label class="gmrc-evidence-check"><input type="checkbox" name="location_ids[]" value="<?php echo esc_attr($location->id()); ?>" <?php checked(in_array($location->id(),$selectedLocations,true)); ?>> <span><?php echo esc_html($location->name()); ?></span></label><?php endforeach; ?><?php endif; ?></fieldset><fieldset><legend>People & factions</legend><?php if(($personae??[])===[]): ?><em>No active Dramatis Personae records yet.</em><?php else: ?><?php foreach($personae as $persona): ?><label class="gmrc-evidence-check"><input type="checkbox" name="persona_ids[]" value="<?php echo esc_attr($persona->id()); ?>" <?php checked(in_array($persona->id(),$selectedPersonae,true)); ?>> <span><?php echo esc_html($persona->name()); ?> <small>· <?php echo esc_html($persona->kindLabel()); ?></small></span></label><?php endforeach; ?><?php endif; ?></fieldset></div>
<p class="gmrc-evidence-form__hint"><strong>Board seam:</strong> these relationships are canonical campaign links. The future Conspiracy Board will visualise them rather than copy them.</p><button class="gmrc-evidence-button" type="submit"><?php echo $editing?'Update Register Record':'Enter Register Record'; ?></button></form>
